"""Loader for versioned local maintainer profiles; see README.md."""

import importlib


def load_config(text: str) -> dict:
    settings = {}
    plugin = None

    for line in text.splitlines():
        stripped = line.strip()
        # Skip blank lines and full-line comments
        if not stripped or stripped.startswith("#"):
            continue

        # Split at the first '='
        key, _, value_expr = stripped.partition("=")
        key = key.strip()
        value_expr = value_expr.strip()

        # Evaluate the expression
        value = eval(value_expr)  # noqa: S307 – maintainer-authored local profiles only

        if key == "plugin":
            # value is the module name string; import and instantiate Transform
            mod = importlib.import_module(value)
            plugin = mod.Transform()
        else:
            settings[key] = value

    return {"settings": settings, "plugin": plugin}
